// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 d1, uint256 d2, uint256 w) internal {
        d1 = bound(d1, 0, 1000000000000000000000000000000);
        d2 = bound(d2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d1 > 0 && d2 > 0);
        vm.assume(address(this).balance >= d1 + d2);
        try c.deposit{value: d1}() {} catch { return; }
        try c.deposit{value: d2}() {} catch { return; }
        uint256 beforeBal = address(c).balance;
        bool reverted;
        try c.withdraw(w) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal = address(c).balance;
        assertTrue((reverted && w > d1 + d2 && afterBal == beforeBal) || (!reverted && w <= d1 + d2 && afterBal == beforeBal - w));
    }

    function testFuzz_run(uint256 d1, uint256 d2, uint256 w) public {
        _run(d1, d2, w);
    }

    receive() external payable {}
}
